factorial:
def main(n):
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result

fib:
def main(n):
    if n <= 1:
        return n
    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b

gcd:
def main(a, b):
    while b:
        a, b = b, a % b
    return a

power:
def main(base, exp):
    if base == 0 and exp == 0:
        return 1
    return base ** exp

collatz-steps:
def main(n):
    steps = 0
    while n != 1:
        if n % 2 == 0:
            n = n // 2
        else:
            n = 3 * n + 1
        steps += 1
    return steps
